func (c *Workspaces) SetNetwork(ctx context.Context, id string, in NetworkRules, opts *RequestOptions) (*SandboxNetwork, error) {
	out := new(SandboxNetwork)
	if err := c.t.Do(ctx, "PUT", "/v2/workspaces/"+url.PathEscape(id)+"/network", nil, in, Call{}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Fork Copies a workspace as it is now, memory and disk, into `count` copies of its own, each running on its host. Asked again with the same Idempotency-Key, it returns the same copies.
func (c *Workspaces) Fork(ctx context.Context, id string, in ForkRequest, opts *RequestOptions) (*Forked, error) {
	out := new(Forked)
	if err := c.t.Do(ctx, "POST", "/v2/workspaces/"+url.PathEscape(id)+":fork", nil, in, Call{Idempotent: true}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Snapshot Keeps a workspace's memory and disk as they are now, a snapshot to start workspaces from; with `image`, its disk alone as that image's next version. The workspace runs on. Asked again with the same Idempotency-Key, it returns the same snapshot.
func (c *Workspaces) Snapshot(ctx context.Context, id string, in SnapshotRequest, opts *RequestOptions) (*Stored, error) {
	out := new(Stored)
	if err := c.t.Do(ctx, "POST", "/v2/workspaces/"+url.PathEscape(id)+":snapshot", nil, in, Call{Idempotent: true}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Update Changes its name, labels, idle pause, maxCost, environment or sizes; each field left out stays as it is. A running one holds a changed environment before this answers (a paused one's at its wake): each process it starts after the answer has it, and its running processes keep the one they started with. Its vCPUs, memory and disk grow while it runs, its commands running on; a smaller size, or a sandbox that is not running, is refused 409 naming why, and nothing is changed. With If-Match, made only while its revision is that one, else 412.
func (c *Workspaces) Update(ctx context.Context, id string, in MachineUpdate, opts *RequestOptions) (*SandboxInfo, error) {
	out := new(SandboxInfo)
	if err := c.t.Do(ctx, "POST", "/v2/workspaces/"+url.PathEscape(id)+":update", nil, in, Call{}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// Screenshot Returns what a workspace's screen shows now, as `image/png` (or `image/jpeg`): its X display `:1`, whole. Refused 409 `display_not_running` when no display runs. A paused workspace is resumed first.
func (c *Workspaces) Screenshot(ctx context.Context, id string, q WorkspaceScreenshotQuery, opts *RequestOptions) ([]byte, error) {
	var out []byte
	if err := c.t.Do(ctx, "GET", "/v2/workspaces/"+url.PathEscape(id)+"/screenshot", q.values(), nil, Call{Idempotent: true}, opts, &out); err != nil {
		return nil, err
	}
	return out, nil
}

// Act Moves, clicks, drags and scrolls the mouse and types on the keyboard of a workspace's screen (its X display `:1`), each step in turn as one command, and returns where the mouse is then. It stops at the first step that fails, refused 409 `act_failed` naming it; refused 409 `display_not_running` when no display runs. A paused workspace is resumed first.
func (c *Workspaces) Act(ctx context.Context, id string, in ActRequest, opts *RequestOptions) (*Acted, error) {
	out := new(Acted)
	if err := c.t.Do(ctx, "POST", "/v2/workspaces/"+url.PathEscape(id)+":act", nil, in, Call{}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// RunCode Runs a cell of Python in a workspace as a notebook does, in a Jupyter kernel it keeps running for the cell's `context`: variables, imports and functions stay for the next cell. Returns what it printed, its values and displays (text, HTML, images such as charts), and its exception with its traceback. The context's kernel starts on its first cell. A cell past `timeoutSeconds` is interrupted and its context kept. Refused 409 `kernel_not_installed` when the image has no ipykernel. A paused workspace is resumed first.
func (c *Workspaces) RunCode(ctx context.Context, id string, in RunCode, opts *RequestOptions) (*CodeRun, error) {
	out := new(CodeRun)
	if err := c.t.Do(ctx, "POST", "/v2/workspaces/"+url.PathEscape(id)+":runCode", nil, in, Call{}, opts, out); err != nil {
		return nil, err
	}
	return out, nil
}

// WorkspaceFiles is a workspace's files.
type WorkspaceFiles struct {
	c  *Workspaces
	id string
}

// Read Returns a file's bytes.
func (g *WorkspaceFiles) Read(ctx context.Context, path string, q *WorkspaceReadQuery, opts *RequestOptions) ([]byte, error) {
	var qb WorkspaceReadQuery
	if q != nil {
		qb = *q
	}
	qb.Path = path
	return g.c.Read(ctx, g.id, qb, opts)
}

// Write Writes the request's bytes to a file as they come, of any size (Content-Length required), its folders made: the file whole when they all came, or as it was. With offset, they are written into it in place.
func (g *WorkspaceFiles) Write(ctx context.Context, path string, data []byte, q *WorkspaceWriteQuery, opts *RequestOptions) (*FileWritten, error) {
	var qb WorkspaceWriteQuery
	if q != nil {
		qb = *q
	}
	qb.Path = path
	return g.c.Write(ctx, g.id, data, qb, opts)
}

// Remove Removes a file, a link or a directory (recursive for one with contents). One missing is success, removed false.
func (g *WorkspaceFiles) Remove(ctx context.Context, path string, in *FileRemove, opts *RequestOptions) (*FileRemoved, error) {
	var b FileRemove
	if in != nil {
		b = *in
	}
	b.Path = path
	return g.c.Remove(ctx, g.id, b, opts)
}

// Stat Returns what is at a path: a file, a directory or a link, or nothing (exists false). With sha256=true, a file's SHA-256 too.
func (g *WorkspaceFiles) Stat(ctx context.Context, path string, q *WorkspaceStatQuery, opts *RequestOptions) (*FileInfo, error) {
	var qb WorkspaceStatQuery
	if q != nil {
		qb = *q
	}
	qb.Path = path
	return g.c.Stat(ctx, g.id, qb, opts)
}

// List Lists a directory's entries in path order, to a depth.
func (g *WorkspaceFiles) List(ctx context.Context, q *WorkspaceListFilesQuery, opts *RequestOptions) (*FileList, error) {
	var qb WorkspaceListFilesQuery
	if q != nil {
		qb = *q
	}
	return g.c.ListFiles(ctx, g.id, qb, opts)
}

// DownloadFolder Returns a folder as a tar archive (`application/x-tar`, or `application/gzip` with gzip), packed by tar in the workspace as it streams, of any size; its entries are relative to the folder (`./a.txt`). A folder that fails part way (a file it may not read, or one that changes as it is read) ends as an archive every tar reader refuses, never as a short one that reads whole. At most 4 at once in a workspace. A paused workspace is woken first.
func (g *WorkspaceFiles) DownloadFolder(ctx context.Context, path string, q *WorkspaceDownloadFolderQuery, opts *RequestOptions) ([]byte, error) {
	var qb WorkspaceDownloadFolderQuery
	if q != nil {
		qb = *q
	}
	qb.Path = path
	return g.c.DownloadFolder(ctx, g.id, qb, opts)
}

// UploadFolder Unpacks the request's tar archive (gzip-compressed or not, told by its first bytes) into a folder, made with its parents, by tar in the workspace as the bytes arrive, of any size, nothing of it kept on disk but what tar writes; returns once tar has ended, or 400 `invalid_archive` with what tar said. A paused workspace is woken first.
func (g *WorkspaceFiles) UploadFolder(ctx context.Context, path string, data []byte, q *WorkspaceUploadFolderQuery, opts *RequestOptions) (*FolderUnpacked, error) {
	var qb WorkspaceUploadFolderQuery
	if q != nil {
		qb = *q
	}
	qb.Path = path
	return g.c.UploadFolder(ctx, g.id, data, qb, opts)
}

// BeginFolderUpload Begins a folder's upload in parts: tar starts in the workspace, unpacking into the folder each part as it arrives. Send the parts in order by offset (writeFolderUpload), then commitFolderUpload; an upload no call names for 10 minutes is ended. A paused workspace is woken first.
func (g *WorkspaceFiles) BeginFolderUpload(ctx context.Context, path string, in *FolderUploadBegin, opts *RequestOptions) (*FolderUpload, error) {
	var b FolderUploadBegin
	if in != nil {
		b = *in
	}
	b.Path = path
	return g.c.BeginFolderUpload(ctx, g.id, b, opts)
}

// WriteFolderUpload Sends the request's bytes, a part of the archive at its offset, into tar's input as they arrive, of any size, and returns the bytes received in all once tar took them. A part past them is refused 409 `upload_incomplete`, naming them: send the parts in order.
func (g *WorkspaceFiles) WriteFolderUpload(ctx context.Context, upload string, data []byte, q *WorkspaceWriteFolderUploadQuery, opts *RequestOptions) (*FolderUploadReceived, error) {
	var qb WorkspaceWriteFolderUploadQuery
	if q != nil {
		qb = *q
	}
	return g.c.WriteFolderUpload(ctx, g.id, upload, data, qb, opts)
}

// CommitFolderUpload Ends a folder upload's input and returns once tar has ended, as an exec returns once its command has: the folder, or 400 `invalid_archive` with what tar said. A front that restarts meanwhile returns 503 `run_goes_on`; sent again, it returns how tar ended. An upload no call has named for 10 minutes since its last part or commit is ended.
func (g *WorkspaceFiles) CommitFolderUpload(ctx context.Context, upload string, opts *RequestOptions) (*FolderUnpacked, error) {
	return g.c.CommitFolderUpload(ctx, g.id, upload, opts)
}

// AbortFolderUpload Stops a folder upload's tar; what it unpacked so far stays.
func (g *WorkspaceFiles) AbortFolderUpload(ctx context.Context, upload string, opts *RequestOptions) (*FolderUploadAborted, error) {
	return g.c.AbortFolderUpload(ctx, g.id, upload, opts)
}

// Mkdir Makes a directory, and its parents unless parents is false. One there already is success, created false.
func (g *WorkspaceFiles) Mkdir(ctx context.Context, path string, in *FileMkdir, opts *RequestOptions) (*FileMade, error) {
	var b FileMkdir
	if in != nil {
		b = *in
	}
	b.Path = path
	return g.c.Mkdir(ctx, g.id, b, opts)
}

// Rename Moves a file, a link or a directory; refused 409 when something is at its new path, unless overwrite. With sha256 or size, a file written in parts is put in place once whole: its writes ended, then only a file of that size with every byte written and whose bytes hash to it moves; refused 409 `upload_incomplete` or `checksum_mismatch`, nothing moved. With sha256, it is safe to send again: once moved, it returns the same answer while `from` is gone and `to` holds those bytes.
func (g *WorkspaceFiles) Rename(ctx context.Context, in *FileRename, opts *RequestOptions) (*FileRenamed, error) {
	var b FileRename
	if in != nil {
		b = *in
	}
	return g.c.Rename(ctx, g.id, b, opts)
}

// Link Makes an expiring address for one file that anyone may open with no API key, from a browser, curl or another service: GET downloads it (Range works, so videos play and downloads resume; archive: true downloads a folder as .tar.gz), PUT with the raw body uploads it (up to maxBytes, written whole; Content-Length required). The link acts as the key that made it: an upload link needs write, and the link ends with its key, with revokeLinks or with its workspace. A paused workspace is woken for it unless wake is false.
func (g *WorkspaceFiles) Link(ctx context.Context, path string, in *FileLinkCreate, opts *RequestOptions) (*FileLink, error) {
	var b FileLinkCreate
	if in != nil {
		b = *in
	}
	b.Path = path
	return g.c.Link(ctx, g.id, b, opts)
}

// RevokeLinks Ends every file link made for a workspace so far; links made after work.
func (g *WorkspaceFiles) RevokeLinks(ctx context.Context, opts *RequestOptions) (*FileLinksRevoked, error) {
	return g.c.RevokeLinks(ctx, g.id, opts)
}

